#!/usr/bin/env python3
import json
import statistics
import sys
import time
import urllib.error
import urllib.request
from collections import Counter
from concurrent.futures import ThreadPoolExecutor, as_completed

BASE = "http://spark-d4c5:8000"
MODEL = "deepseek-v4-flash-0731"
TIMEOUT = 300
REQUESTS = 64
CONCURRENCY = 8

WEATHER = {
    "type": "function",
    "function": {
        "name": "get_weather",
        "description": "Get current weather for a location.",
        "parameters": {
            "type": "object",
            "properties": {
                "location": {"type": "string"},
                "unit": {"type": "string", "enum": ["celsius", "fahrenheit"]},
            },
            "required": ["location", "unit"],
            "additionalProperties": False,
        },
    },
}
TIME = {
    "type": "function",
    "function": {
        "name": "get_local_time",
        "description": "Get local time for a location.",
        "parameters": {
            "type": "object",
            "properties": {"location": {"type": "string"}},
            "required": ["location"],
            "additionalProperties": False,
        },
    },
}
COMPUTE = {
    "type": "function",
    "function": {
        "name": "compute_total",
        "description": "Perform arithmetic over integer values.",
        "strict": True,
        "parameters": {
            "type": "object",
            "properties": {
                "operation": {"type": "string", "enum": ["add", "multiply"]},
                "values": {"type": "array", "items": {"type": "integer"}, "minItems": 2, "maxItems": 2},
                "rounded": {"type": "boolean"},
                "label": {"type": "string"},
            },
            "required": ["operation", "values", "rounded", "label"],
            "additionalProperties": False,
        },
    },
}
TOOLS = [WEATHER, TIME, COMPUTE]
CITIES = [
    "Lisbon", "Oslo", "Cairo", "Seoul", "Lima", "Auckland", "Montréal", "Reykjavík",
    "Nairobi", "Singapore", "Warsaw", "Brisbane", "Bogotá", "Helsinki", "Mumbai", "Vienna",
]


def health():
    try:
        with urllib.request.urlopen(f"{BASE}/health", timeout=10) as response:
            return response.status
    except Exception as exc:
        return f"ERROR: {exc}"


def payload_for(index):
    city = CITIES[index % len(CITIES)]
    mode = index % 4
    if mode == 0:
        expected_name = "get_weather"
        expected = {"city": city, "unit": "celsius"}
        payload = {
            "messages": [{"role": "user", "content": f"Call get_weather for {city} using Celsius."}],
            "tools": TOOLS,
            "tool_choice": {"type": "function", "function": {"name": "get_weather"}},
        }
    elif mode == 1:
        expected_name = "get_local_time"
        expected = {"city": city}
        payload = {
            "messages": [{"role": "user", "content": f"Use the appropriate tool to get the current local time in {city}."}],
            "tools": [WEATHER, TIME],
            "tool_choice": "required",
        }
    elif mode == 2:
        left = index + 3
        right = index + 5
        expected_name = "compute_total"
        expected = {"values": [left, right]}
        payload = {
            "messages": [{"role": "user", "content": f"Call compute_total to add integers {left} and {right}; rounded false; label batch-{index}."}],
            "tools": TOOLS,
            "tool_choice": {"type": "function", "function": {"name": "compute_total"}},
        }
    else:
        expected_name = "get_weather"
        expected = {"city": city, "unit": "fahrenheit"}
        payload = {
            "messages": [{"role": "user", "content": f"You must call get_weather for {city} using Fahrenheit."}],
            "tools": [WEATHER, TIME],
            "tool_choice": "auto",
        }
    return payload, expected_name, expected


def run_one(index):
    payload, expected_name, expected = payload_for(index)
    body = json.dumps({"model": MODEL, "temperature": 0, "max_tokens": 192, **payload}).encode()
    request = urllib.request.Request(
        f"{BASE}/v1/chat/completions",
        data=body,
        headers={"Content-Type": "application/json"},
    )
    started = time.monotonic()
    try:
        with urllib.request.urlopen(request, timeout=TIMEOUT) as response:
            status = response.status
            data = json.loads(response.read())
    except urllib.error.HTTPError as exc:
        return {"index": index, "passed": False, "status": exc.code, "error": exc.read().decode(errors="replace"), "elapsed_s": round(time.monotonic() - started, 3)}
    elapsed = time.monotonic() - started
    try:
        assert status == 200, status
        choices = data.get("choices") or []
        assert len(choices) == 1, data
        choice = choices[0]
        assert choice.get("finish_reason") in {"tool_calls", "stop"}, choice
        calls = choice["message"].get("tool_calls") or []
        assert len(calls) == 1, calls
        call = calls[0]
        assert call.get("id"), call
        function = call.get("function") or {}
        assert function.get("name") == expected_name, function
        args = json.loads(function["arguments"])
        assert isinstance(args, dict), args
        if expected_name == "get_weather":
            assert expected["city"].casefold() in args["location"].casefold(), (expected, args)
            assert args["unit"] == expected["unit"], (expected, args)
        elif expected_name == "get_local_time":
            assert expected["city"].casefold() in args["location"].casefold(), (expected, args)
        else:
            assert args == {
                "operation": "add",
                "values": expected["values"],
                "rounded": False,
                "label": f"batch-{index}",
            }, (expected, args)
        return {
            "index": index,
            "passed": True,
            "name": expected_name,
            "finish_reason": choice.get("finish_reason"),
            "elapsed_s": round(elapsed, 3),
        }
    except Exception as exc:
        return {"index": index, "passed": False, "status": status, "error": repr(exc), "response": data, "elapsed_s": round(elapsed, 3)}


started = time.monotonic()
print(f"START requests={REQUESTS} concurrency={CONCURRENCY} health={health()}", flush=True)
results = []
with ThreadPoolExecutor(max_workers=CONCURRENCY) as executor:
    futures = [executor.submit(run_one, index) for index in range(REQUESTS)]
    for future in as_completed(futures):
        result = future.result()
        results.append(result)
        if not result["passed"]:
            print("FAIL " + json.dumps(result, sort_keys=True), flush=True)

latencies = sorted(result["elapsed_s"] for result in results)
def percentile(fraction):
    if not latencies:
        return None
    return latencies[min(len(latencies) - 1, int(round((len(latencies) - 1) * fraction)))]

summary = {
    "requests": REQUESTS,
    "concurrency": CONCURRENCY,
    "passed": sum(result["passed"] for result in results),
    "failed": sum(not result["passed"] for result in results),
    "names": dict(Counter(result.get("name") for result in results if result["passed"])),
    "finish_reasons": dict(Counter(result.get("finish_reason") for result in results if result["passed"])),
    "protocol_finish_reason_violations": sum(
        result.get("finish_reason") != "tool_calls" for result in results if result["passed"]
    ),
    "latency_s": {
        "min": min(latencies) if latencies else None,
        "median": round(statistics.median(latencies), 3) if latencies else None,
        "p95": percentile(0.95),
        "max": max(latencies) if latencies else None,
    },
    "wall_s": round(time.monotonic() - started, 3),
    "health": health(),
}
print("SUMMARY " + json.dumps(summary, sort_keys=True), flush=True)
sys.exit(1 if summary["failed"] or summary["health"] != 200 else 0)
